DO $$ BEGIN IF to_regclass('public.__diesel_schema_migrations') IS NOT NULL THEN IF to_regclass('zc_private.__diesel_schema_migrations') IS NOT NULL THEN RAISE EXCEPTION 'Both public and zc_private Diesel ledgers exist'; END IF; ALTER TABLE public.__diesel_schema_migrations SET SCHEMA zc_private; ELSE CREATE TABLE IF NOT EXISTS zc_private.__diesel_schema_migrations (version VARCHAR(50) PRIMARY KEY NOT NULL, run_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP); END IF; END $$
